  <div class="container">
    <div class="brand-bar"></div>
    <div class="content">
      @if (!string.IsNullOrWhiteSpace(logo))
      {
        <a href="@website" target="_blank">
          <img class="logo" src="@logo" alt="@product" style="display: block; margin: 0 auto;">
        </a>
        <br/>
      }
      <p class="badge">Updates required</p>
      <h1 class="title">Updates are required for your job posting</h1>
      <p class="text">Dear Colleague,</p>
      <p class="text">
        The job posting @(string.IsNullOrWhiteSpace(jobTitle) ? "" : $" <strong>\"{jobTitle}\"</strong>") requires updates before it can be approved.
      </p>
      <p class="text">
        Please sign in to @product, review the requested changes, and resubmit the posting.
      </p>
      <a class="cta" style="color: white;" href="@website" target="_blank">Update in @product</a>
      <div class="divider"></div>
      <p class="muted">
        If the button does not work, copy and paste this link into your browser: @website
      </p>
    </div>
    <div class="footer">
      <p class="muted">Regards,<br>@product Team</p>
      <p class="muted">Support: <a href="mailto:@support" style="color:@primary; text-decoration:none;" target="_blank">@support</a></p>
      <p class="muted">© @(DateTime.UtcNow.Year) @product. All rights reserved.</p>
    </div>
  </div>
</body>
</html>

OfficeCreatedNotification.OfficeCreatedNotification.txt.cshtml:
@model Tawtheef.Notifications.Context.TemplateContext<Tawtheef.Notifications.Templates.OfficeCreatedNotification.OfficeCreatedNotificationModel>

@{
    var b = Model.Branding;
    var m = Model.Model;

    var product = b.ProductName;
    var support = b.SupportEmail;
    var website = b.WebsiteUrl;

    var officeName = string.IsNullOrWhiteSpace(m.OfficeNameEn) ? "New Office" : m.OfficeNameEn;
    var officeCode = string.IsNullOrWhiteSpace(m.OfficeCode) ? "-" : m.OfficeCode;
    var adminEmail = string.IsNullOrWhiteSpace(m.AdminEmail) ? "your account" : m.AdminEmail;
}

Subject: @($"{product} - Recruitment Office Created")

Dear Administrator,

A new recruitment office has been successfully created in @product.

Office Details:
- Office Name: @officeName
- Office Code: @officeCode
- Administrator Email: @adminEmail

Access Instructions:
1) Ensure you are connected to the corporate VPN (if required)
2) Visit the platform: @website
3) Login using your assigned email: @adminEmail

If you need assistance, please contact support: @support

Regards,
The @product Team

