<body class="email-wrap" style="background:#f7f4f6; margin:0; padding:20px; direction: rtl;">
  <div class="preheader">
    @preheader
  </div>

  <table role="presentation" style="width: 100%; background:#f7f4f6;" dir="rtl">
    <tr>
      <td style="padding:20px;">
        <table role="presentation" class="container" align="center">
          <tr>
            <td class="brand-bar" aria-hidden="true">&nbsp;</td>
          </tr>
          <tr>
            <td class="px" style="padding-top:18px; padding-bottom:12px;">
              <table role="presentation" style="width:100%;">
                <tr>
                  <td style="vertical-align:middle; text-align: right;">
                    @if (!string.IsNullOrWhiteSpace(logo))
