<body class="email-wrap" style="background:#f7f4f6; margin:0; padding:20px;">
  <!-- Preheader text -->
  <div class="preheader">
    @preheader
  </div>

  <table role="presentation" style="background:#f7f4f6;">
    <tr>
      <td style="padding:20px;">
        <table role="presentation" class="container">

          <!-- Brand bar -->
          <tr>
            <td class="brand-bar" aria-hidden="true">&nbsp;</td>
          </tr>

          <!-- Header -->
          <tr>
            <td class="px" style="padding-top:18px; padding-bottom:12px;">
              <table role="presentation" style="width:100%;">
                <tr>
                  <td style="vertical-align:middle;">
                    @if (!string.IsNullOrWhiteSpace(logo))
                    {
                      <a href="@website" style="display:inline-block;" target="_blank">
                        <img src="@logo" alt="@product" width="140" style="max-width:140px; height:auto;">
                      </a>
                    }
                    else
                    {
                      <div style="font-family:Arial, sans-serif; font-weight:800; font-size:18px; color:@primary;">
                        @product
                      </div>
                    }
                  </td>
                  <td style="vertical-align:middle; text-align:right;">
                    <span class="badge">@badgeText</span>
                  </td>
                </tr>
              </table>
            </td>
          </tr>

          <tr>
            <td class="px">
              <div class="divider"></div>
            </td>
          </tr>

          <!-- Body -->
          <tr>
            <td class="px py">
              <h2 class="h2">@title</h2>

              @if (isAccepted)
              {
                <p class="text">
                  We’re pleased to inform you that your profile has been <strong>approved</strong> on
                  <span class="accent" style="color:@primary; font-weight:800;">@product</span>.
                </p>

                <p class="text" style="margin-bottom:18px;">
                  You can now continue using the platform normally.
                </p>
              }
              else
              {
                <p class="text">
                  Your profile has been <strong>returned for updates</strong>.
                  Please review the notes below, make the required changes, then resubmit your profile.
                </p>

                @if (!string.IsNullOrWhiteSpace(notes) || (reasons != null && reasons.Any()))
                {
                  <div class="notes-box" style="margin-top:10px; margin-bottom:16px;">
                    <div class="notes-title">Review Notes</div>

                    @if (!string.IsNullOrWhiteSpace(notes))
                    {
                      <p class="notes-item" style="margin-bottom:0;">@notes</p>
                    }

                    @if (reasons != null && reasons.Any())
                    {
                      <ul style="padding-left:18px; margin:10px 0 0 0;">
                        @foreach (var r in reasons)
                        {
                          if (!string.IsNullOrWhiteSpace(r))
                          {
                            <li class="notes-item">@r</li>
                          }
                        }
                      </ul>
                    }
                  </div>
                }
              }

              @if (profileUrl != null)
              {
                  <a href="@profileUrl" class="btn" target="_blank">Open Profile</a>
              }

              <p class="text" style="margin-top:16px; margin-bottom:0;">
                If you need assistance, contact our support team and we’ll be happy to help.
              </p>
            </td>
          </tr>

          <tr>
            <td class="px">
              <div class="divider"></div>
            </td>
          </tr>

          <!-- Help / Support -->
          @* <tr>
            <td class="px py" style="padding-top:18px; padding-bottom:12px;">
              <p class="muted">
                Need help? Contact us at
                <a href="mailto:@support" style="color:@primary; font-weight:700;" target="_blank">@support</a>.
              </p>
            </td>
          </tr> *@

          <!-- Footer -->
          <tr>
            <td class="px" style="padding-bottom:22px;">
              <p class="muted">
                Sent by <span class="accent" style="color:@primary; font-weight:700;">@product</span>
              </p>
              <p class="muted" style="margin-top:6px;">
                © @(DateTime.UtcNow.Year) @product. All rights reserved.
              </p>
            </td>
          </tr>

        </table>
      </td>
    </tr>
  </table>
</body>
</html>

